                            seen.add((ny, nx))
                            stack.append((ny, nx))
                result.append(comp)
        return result

    # Find a one-cell-wide L-shaped component.
    guide = None
    for color in counts:
        if color == bg:
            continue
        for comp in components(color):
            cells = set(comp)
            ys = [r for r, c in comp]
            xs = [c for r, c in comp]
            r0, r1, c0, c1 = min(ys), max(ys), min(xs), max(xs)
            if r0 == r1 or c0 == c1:
                continue
            for er, ec in ((r0, c0), (r0, c1), (r1, c0), (r1, c1)):
                expected = ({(r, ec) for r in range(r0, r1 + 1)} |
                            {(er, c) for c in range(c0, c1 + 1)})
                if cells == expected:
