    # Locate which way each arm extends from the elbow.
    vertical_sign = -1 if er == r1 else 1
    horizontal_sign = -1 if ec == c1 else 1
    target_r_sign = -vertical_sign
    target_c_sign = -horizontal_sign

    targets = []
    for other in counts:
        if other in (bg, color):
            continue
        for comp in components(other):
            cy = sum(r for r, c in comp) / len(comp)
            cx = sum(c for r, c in comp) / len(comp)
